begin;
select set_config('rf.owner',gen_random_uuid()::text,true),set_config('rf.member',gen_random_uuid()::text,true),set_config('rf.other',gen_random_uuid()::text,true),set_config('rf.product',gen_random_uuid()::text,true),set_config('rf.customer',gen_random_uuid()::text,true),set_config('rf.sale',gen_random_uuid()::text,true),set_config('rf.partial',gen_random_uuid()::text,true),set_config('rf.cashfail',gen_random_uuid()::text,true),set_config('rf.zero',gen_random_uuid()::text,true),set_config('rf.credit',gen_random_uuid()::text,true),set_config('rf.owner_sale',gen_random_uuid()::text,true),set_config('rf.refund',gen_random_uuid()::text,true),set_config('rf.owner_refund',gen_random_uuid()::text,true),set_config('rf.action',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('rf.owner')::uuid,'refund-owner@example.invalid'),(current_setting('rf.member')::uuid,'refund-member@example.invalid'),(current_setting('rf.other')::uuid,'refund-other@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,sale_price) values(current_setting('rf.product')::uuid,'Refund item',1000);
insert into public.customers(id,name) values(current_setting('rf.customer')::uuid,'Credit customer');
select public.post_purchase(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','10000','unit_cost','500')),'','','');
select public.post_cash_sale(current_setting('rf.owner_sale')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),0,1000,'Owner receipt','');
select public.save_store_cashier(current_setting('rf.action')::uuid,current_setting('rf.member')::uuid,'Refund cashier','Store',true,true,0,'manager',true,true);
select set_config('rf.membership',(public.get_staff_workspace()->'cashiers'->0->>'id'),true);
do $$begin if(public.get_staff_workspace()->'cashiers'->0->>'can_refund')::boolean then raise exception 'implicit refund grant';end if;end $$;
reset role;update public.staff_actions set request_payload=request_payload-'refund' where id=current_setting('rf.action')::uuid;set local role authenticated;
select public.save_store_cashier(current_setting('rf.action')::uuid,current_setting('rf.member')::uuid,'Refund cashier','Store',true,true,0,'manager',true,true);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.member'),'role','authenticated')::text,true);set local role authenticated;
do $$begin begin perform public.get_cashier_refund_workspace(current_setting('rf.owner')::uuid);raise exception 'unaccepted';exception when raise_exception then if sqlerrm<>'staff_access_denied' then raise;end if;end;end $$;
select public.accept_store_cashier(gen_random_uuid(),current_setting('rf.membership')::uuid);
select public.post_cashier_sale(current_setting('rf.owner')::uuid,current_setting('rf.sale')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),100,2000,'Saved customer','cash sale');
select public.post_cashier_sale(current_setting('rf.owner')::uuid,current_setting('rf.partial')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),0,1000,'','');
select public.post_cashier_sale(current_setting('rf.owner')::uuid,current_setting('rf.cashfail')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),0,1000,'','');
select public.post_cashier_sale(current_setting('rf.owner')::uuid,current_setting('rf.zero')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),1000,0,'','');
select public.post_cashier_credit_sale(current_setting('rf.owner')::uuid,current_setting('rf.credit')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('rf.product'),'quantity_units','1000','expected_price','1000')),0,200,current_setting('rf.customer')::uuid,'');
do $$begin
 if exists(select 1 from public.sales) or exists(select 1 from public.sale_returns) then raise exception 'raw RLS exposed';end if;
 begin perform public.post_cashier_partial_return(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.sale')::uuid,'Default denied','[{"line_no":1,"quantity_units":"250"}]',0);raise exception 'implicit partial grant';exception when raise_exception then if sqlerrm<>'staff_partial_denied' then raise;end if;end;
 begin perform private.post_sale_return_for_owner(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.sale')::uuid,'Core denied','[{"line_no":1,"quantity_units":"250"}]');raise exception 'core exposed';exception when insufficient_privilege then null;end;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
select public.save_store_cashier(gen_random_uuid(),current_setting('rf.member')::uuid,'Partial cashier','Store',true,true,2,'cashier',true,true,false,true);
select public.post_sale_return(gen_random_uuid(),current_setting('rf.sale')::uuid,'Owner first','[{"line_no":1,"quantity_units":"250"}]');
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.member'),'role','authenticated')::text,true);set local role authenticated;
do $$declare x jsonb;begin
 x:=public.get_cashier_partial_source(current_setting('rf.owner')::uuid,current_setting('rf.sale')::uuid);
 if x#>>'{context,count}'<>'1' or x#>>'{context,states,0,returned_units}'<>'250' or x#>>'{context,states,0,refunded}'<>'225' or x->>'can_partial_refund'<>'true' then raise exception 'owner history not counted';end if;
 begin perform public.post_cashier_partial_return(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.sale')::uuid,'Stale','[{"line_no":1,"quantity_units":"250"}]',0);raise exception 'stale accepted';exception when raise_exception then if sqlerrm<>'staff_return_changed' then raise;end if;end;
 begin perform public.post_cashier_partial_return(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.sale')::uuid,'Excess','[{"line_no":1,"quantity_units":"751"}]',1);raise exception 'excess accepted';exception when raise_exception then if sqlerrm<>'return_quantity_exceeds_remaining' then raise;end if;end;
 begin perform public.get_cashier_partial_source(current_setting('rf.owner')::uuid,current_setting('rf.credit')::uuid);raise exception 'credit accepted';exception when raise_exception then if sqlerrm<>'staff_refund_cash_only' then raise;end if;end;
 begin perform public.get_cashier_partial_source(current_setting('rf.owner')::uuid,current_setting('rf.owner_sale')::uuid);raise exception 'other actor accepted';exception when raise_exception then if sqlerrm<>'staff_sale_unavailable' then raise;end if;end;
 x:=public.post_cashier_partial_return(current_setting('rf.owner')::uuid,current_setting('rf.refund')::uuid,current_setting('rf.sale')::uuid,'Selected goods returned','[{"line_no":1,"quantity_units":"250"}]',1);
 if x#>>'{returned,total}'<>'225' or x#>>'{returned,cash_refund}'<>'225' or x#>>'{returned,actor_id}'<>current_setting('rf.member') or x#>>'{returned,actor_name}'<>'Partial cashier' or x#>>'{returned,staff_context,count}'<>'1' then raise exception 'partial document failed';end if;
 perform public.post_cashier_partial_return(current_setting('rf.owner')::uuid,current_setting('rf.refund')::uuid,current_setting('rf.sale')::uuid,'Selected goods returned','[{"line_no":1,"quantity_units":"250"}]',1);
 begin perform public.post_cashier_partial_return(current_setting('rf.owner')::uuid,current_setting('rf.refund')::uuid,current_setting('rf.sale')::uuid,'Changed reason','[{"line_no":1,"quantity_units":"250"}]',1);raise exception 'conflict accepted';exception when raise_exception then if sqlerrm<>'return_request_conflict' then raise;end if;end;
end $$;
select public.post_cashier_repayment(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.customer')::uuid,100,'Cash collected',800);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
select public.save_store_cashier(gen_random_uuid(),current_setting('rf.member')::uuid,'Report cashier','Store',true,true,3,'cashier',true,true,true,true);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.member'),'role','authenticated')::text,true);set local role authenticated;
select public.post_cashier_refund(current_setting('rf.owner')::uuid,gen_random_uuid(),current_setting('rf.cashfail')::uuid,'Full return');
select set_config('ca.day',(now() at time zone 'Asia/Baghdad')::date::text,true);
do $$declare x jsonb;begin
 x:=public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date);
 if x#>>'{summary,sale_cash}'<>'2900' or x#>>'{summary,sale_credit_cash}'<>'200' or x#>>'{summary,collection}'<>'100' or x#>>'{summary,full_refund}'<>'1000' or x#>>'{summary,partial_refund}'<>'225' or x#>>'{summary,inflow}'<>'3200' or x#>>'{summary,outflow}'<>'1225' or x#>>'{summary,net}'<>'1975' or x#>>'{summary,count}'<>'8' then raise exception 'cash report arithmetic: %',x;end if;
 if exists(select 1 from jsonb_array_elements(x->'rows')r where r->>'actor_id'<>current_setting('rf.member') or r->>'id'=current_setting('rf.owner_sale')) then raise exception 'other actor exposed';end if;
 if exists(select 1 from public.cash_movements) or exists(select 1 from public.sales) then raise exception 'raw owner RLS changed';end if;
 begin perform public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date+31);raise exception 'wide range accepted';exception when raise_exception then if sqlerrm<>'staff_cash_invalid_range' then raise;end if;end;
 begin perform public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date-1);raise exception 'reversed range accepted';exception when raise_exception then if sqlerrm<>'staff_cash_invalid_range' then raise;end if;end;
 x:=public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date-30,current_setting('ca.day')::date-30);
 if x#>>'{summary,count}'<>'0' or x#>>'{summary,net}'<>'0' then raise exception 'empty period wrong';end if;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
select public.save_store_cashier(gen_random_uuid(),current_setting('rf.member')::uuid,'Report cashier','Store',false,true,4,'cashier',false,false,false,false);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.other'),'role','authenticated')::text,true);set local role authenticated;
do $$begin begin perform public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date);raise exception 'stranger accepted';exception when raise_exception then if sqlerrm<>'staff_access_denied' then raise;end if;end;end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
select public.save_store_cashier(gen_random_uuid(),current_setting('rf.member')::uuid,'Report cashier','Store',false,false,5,'cashier',false,false,false,false);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.member'),'role','authenticated')::text,true);set local role authenticated;
do $$begin begin perform public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date);raise exception 'suspended accepted';exception when raise_exception then if sqlerrm<>'staff_access_denied' then raise;end if;end;end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.owner'),'role','authenticated')::text,true);set local role authenticated;
select public.save_store_cashier(gen_random_uuid(),current_setting('rf.member')::uuid,'Report cashier','Store',false,true,6,'cashier',false,false,false,false);
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('rf.member'),'role','authenticated')::text,true);set local role authenticated;
do $$begin if has_function_privilege('anon','public.get_cashier_cash_activity(uuid,date,date)','execute') then raise exception 'anon granted';end if;end $$;
select jsonb_build_object('owner',current_setting('rf.owner'),'actor',current_setting('rf.member'),'report',public.get_cashier_cash_activity(current_setting('rf.owner')::uuid,current_setting('ca.day')::date,current_setting('ca.day')::date)) as client_snapshot;
rollback;
